cv.addEventListener('contextmenu',e=>{e.preventDefault();if(draft.length)finish();else if(selected.size)duplicate()});
function ensureCapacity(n){if(plan.items.length+n>C.MAX_ITEMS)throw Error('This plan has reached its object limit. Start a second plan for the next area.')}
function tap(p){try{if(mode==='symbol'){addSymbol(p);return}if(mode==='corner'){addCorner(p);return}if(mode==='pin'){const ll=C.toLatLng(p,plan.origin);plan.location={lat:ll.lat,lng:ll.lng,label:'Site entrance',words:null,accuracy:null};renderLocation();queueSave();setMode('select');toast('Entrance marked. Use /// to get its what3words address.');return}if(mode==='panel'||mode==='accessory'){ensureCapacity(1);if(!Number.isFinite(+$('angle').value))throw Error('Enter a valid panel rotation.');checkpoint();const kind=mode==='panel'?'panel':'accessory',k=$(kind==='panel'?'product':'accessory').value,a=kind==='panel'?catalog[k]:C.ACCESSORIES[k],q={id:C.id(),kind,product:k,name:a.name,colour:a.colour,l:a.l,w:a.w,wedge:a.wedge,dir:a.dir,x:p.x,y:p.y,a:(+$('angle').value||0)*C.DEG};plan.items.push(q);selected=new Set([q.id]);if($('snap').checked)C.snap(plan.items,selected,Math.min(.7,12/pixelsPerMetre()));changed()}else if(mode==='text'){const t=$('labelText').value.trim();if(!t){toast('Enter a label in the tools panel first.');return}ensureCapacity(1);checkpoint();const q={id:C.id(),kind:'text',text:t,x:p.x,y:p.y,a:0,size:+$('annSize').value,colour:$('annColour').value};plan.items.push(q);changed()}else{if(draft.length&&C.distance(draft[draft.length-1],p)<.03)return;draft.push(p);if(draft.length===2&&['measure','line','shape'].includes(mode))finish();renderDraft();draw()}}catch(e){toast(e.message)}}
function finish(){
 if(calibrating)return;
 try{
  let added=[],result=null,source=null;const route=['route','freeRoute'].includes(mode),pad=['pad','freePad'].includes(mode),product=$('product').value,lanes=+$('routeWidth').value;
  if(route){result=D.route(draft,product,lanes,catalog,{freehand:mode==='freeRoute',stagger:+$('maxStagger').value});added=result.items;const g=result.points;lastRouteAngle=Math.atan2(g[g.length-1].y-g[g.length-2].y,g[g.length-1].x-g[g.length-2].x)}
  else if(pad){const previous=(plan.paths||[]).filter(q=>['route','freeRoute'].includes(q.mode)&&validPath(q)).at(-1),g=previous?.points;const heading=lastRouteAngle??(g?.length>1?Math.atan2(g.at(-1).y-g.at(-2).y,g.at(-1).x-g.at(-2).x):undefined);const alignment=$('areaAlign').value,angle=alignment==='angle'?+$('angle').value*C.DEG:['route','auto'].includes(alignment)?heading:undefined;added=D.pad(draft,product,catalog,angle);if(!added.length)throw Error('No full panels fit inside this boundary. Enlarge it or choose another angle.')}
  else if(draft.length===2){if(mode==='measure'||mode==='line')added=[{id:C.id(),kind:mode,points:structuredClone(draft),colour:mode==='measure'?'#d1281e':$('annColour').value,dash:$('lineStyle').value}];else if(mode==='shape'){const[a,b]=draft,l=Math.abs(a.x-b.x),w=Math.abs(a.y-b.y);if(l<.05||w<.05)throw Error('Choose two different opposite corners.');added=[{id:C.id(),kind:$('shapeKind').value,x:(a.x+b.x)/2,y:(a.y+b.y)/2,l,w,a:0,colour:$('annColour').value,alpha:+$('opacity').value,dash:$('lineStyle').value}]}}
  else throw Error('Add the remaining points first.');
  if(!added.length)throw Error('No panels could be placed without overlap. Adjust the route.');
  const replaced=new Set(editingPath?.itemIds||[]);if(plan.items.length-replaced.size+added.length>C.MAX_ITEMS)throw Error('Split this plan into smaller sections.');
  if(route||pad)source={id:C.id(),mode,product,lanes,points:structuredClone(route?result.points:draft),angle:added[0].a,itemIds:added.map(q=>q.id),fingerprint:pathFingerprint(added),joints:result?.joints||[]};
  checkpoint();if(editingPath){plan.items=plan.items.filter(q=>!replaced.has(q.id));plan.paths=(plan.paths||[]).filter(q=>q.id!==editingPath.id)}
  plan.items.push(...added);if(source)(plan.paths||(plan.paths=[])).push(source);
  draft=[];activeVertex=-1;editingPath=null;selected=new Set(added.map(q=>q.id));setMode('select');changed();
  if(route)toast(`${added.length} panels · ${result.joints.length} bends to review${result.omitted?' · '+result.omitted+' overlapping positions omitted':''}${result.staggered?' · limited Sabre offset used':''}. Orange markers identify joints to check.`);
  else if(pad)toast(added.length+' full panels fitted inside the outline, on one aligned grid.');else toast('Added to your plan.');
 }catch(e){toast(e.message)}
}
function zoom(delta,p={x:cv.clientWidth/2,y:cv.clientHeight/2}){if(locked&&!frameMode){toast('Unlock the map to change the view.');return}if(plan.background.type==='image'){const before=world(p);view.z=Math.max(.15,Math.min(15,view.z*(delta>0?1.25:.8)));const after=screen(before);view.x+=p.x-after.x;view.y+=p.y-after.y;draw();queueSave()}else map.setZoomAround([p.x,p.y],Math.max(3,Math.min(22,map.getZoom()+delta)))}
function fitPlan(){if(locked&&!frameMode){toast('Unlock the map before fitting the view.');return}const b=C.bounds(plan.items);if(plan.background.type==='image'){view={z:1,x:0,y:0};draw();queueSave();return}if(b){const a=C.toLatLng({x:b.minX,y:b.minY},plan.origin),c=C.toLatLng({x:b.maxX,y:b.maxY},plan.origin);map.fitBounds([[a.lat,a.lng],[c.lat,c.lng]],{paddingTopLeft:[50,155],paddingBottomRight:[90,170],maxZoom:21})}else if(plan.location)map.setView([plan.location.lat,plan.location.lng],18);else map.setView([plan.origin.lat,plan.origin.lng],18)}
function copy(){clipboard=plan.items.filter(q=>selected.has(q.id)).map(q=>structuredClone(q));if(clipboard.length)toast(clipboard.length+' objects copied.')}
function paste(){if(!clipboard.length)return;try{ensureCapacity(clipboard.length);checkpoint();const ids=new Map(clipboard.map(q=>[q.id,C.id()])),groups=new Map();const out=clipboard.map(o=>{const q=structuredClone(o);q.id=ids.get(o.id);if(q.group){if(!groups.has(q.group))groups.set(q.group,C.id());q.group=groups.get(q.group)}q.parent=ids.get(q.parent);C.translate(q,18/pixelsPerMetre(),18/pixelsPerMetre());return q});plan.items.push(...out);selected=new Set(out.map(q=>q.id));changed()}catch(e){toast(e.message)}}
function duplicate(){clipboard=plan.items.filter(q=>selected.has(q.id)).map(q=>structuredClone(q));paste()}
function deleteSelected(){if(activeVertex>=0){removePoint();return}if(!selected.size)return;checkpoint();plan.items=plan.items.filter(q=>!selected.has(q.id));plan.items.forEach(q=>{if(selected.has(q.parent))delete q.parent});selected.clear();changed()}
function rotateSelected(degrees){if(!selected.size)return;checkpoint();const chosen=plan.items.filter(q=>selected.has(q.id)),b=C.bounds(chosen),center={x:(b.minX+b.maxX)/2,y:(b.minY+b.maxY)/2},a=degrees*C.DEG;chosen.forEach(q=>{if(q.points)q.points=q.points.map(p=>C.rotate(p,a,center));else{const p=C.rotate(q,a,center);q.x=p.x;q.y=p.y;q.a=(q.a||0)+a}});changed()}
function groupSelection(){if(!selected.size)return;checkpoint();const chosen=plan.items.filter(q=>selected.has(q.id)),same=chosen[0].group&&chosen.every(q=>q.group===chosen[0].group);if(same){chosen.forEach(q=>delete q.group);toast('Objects ungrouped.')}else if(chosen.length>1){const id=C.id();chosen.forEach(q=>q.group=id);toast('Selection grouped.')}else toast('Select more than one object to group.');changed()}
function modal(title,html){$('modalTitle').textContent=title;$('modalBody').innerHTML=html;icons($('modalBody'));if(!$('modal').open)$('modal').showModal()}
function closeModal(){$('modal').close()}
function normalWords(s){return s.trim().toLowerCase().replace(/^https?:\/\/(?:www\.)?(?:what3words\.com|w3w\.co)\//,'').replace(/^\/+/, '').replace(/[。｡･・]/g,'.').replace(/\s+/g,'')}
async function fetchJSON(url){const ac=new AbortController(),timer=setTimeout(()=>ac.abort(),14000);try{const r=await fetch(url,{signal:ac.signal,referrerPolicy:'strict-origin-when-cross-origin'}),d=await r.json();if(!r.ok||d.error)throw Error(typeof d.error==='string'?d.error:d.error?.message||'The location service is unavailable.');return d}catch(e){if(e.name==='AbortError')throw Error('The lookup timed out. Check your connection and try again.');throw e}finally{clearTimeout(timer)}}
async function searchSite(e){e?.preventDefault();const raw=$('search').value.trim();if(!raw)return;if(Date.now()-lastSearch<1000)return;const seq=++currentSearch;lastSearch=Date.now();const btn=$('searchForm').querySelector('button');btn.disabled=true;$('searchResults').hidden=true;try{const coord=raw.match(/^\s*(-?\d+(?:\.\d+)?)\s*[,;]\s*(-?\d+(?:\.\d+)?)\s*$/);if(coord){const lat=+coord[1],lng=+coord[2];if(Math.abs(lat)>85||Math.abs(lng)>180)throw Error('Enter latitude, longitude within the map’s supported range.');gotoLocation(lat,lng,lat.toFixed(6)+', '+lng.toFixed(6));return}const words=normalWords(raw);if(/^[\p{L}]+\.[\p{L}]+\.[\p{L}]+$/u.test(words)){if(!getW3WKey()){w3wDialog(words);return}const d=await fetchJSON('https://api.what3words.com/v3/convert-to-coordinates?'+new URLSearchParams({words,key:getW3WKey()}));if(seq!==currentSearch)return;gotoLocation(d.coordinates.lat,d.coordinates.lng,'///'+d.words,d.words);return}const postcode=raw.replace(/\s/g,'');if(/^(GIR0AA|[A-Z]{1,2}\d[A-Z\d]?\d[A-Z]{2})$/i.test(postcode)){const d=await fetchJSON('https://api.postcodes.io/postcodes/'+encodeURIComponent(postcode));if(seq!==currentSearch)return;gotoLocation(d.result.latitude,d.result.longitude,d.result.postcode+' · '+(d.result.admin_district||''));return}if(!getMapKey()){modal('Search by address','<p>UK postcodes, coordinates and current location are ready to use. Full street-address search uses a Mapbox connection.</p><button class="btn primary full" data-action="settings">Connect Mapbox</button><p class="fineprint">You can also find your site by moving the map.</p>');return}const url=(cfg.geocodingUrl||'https://api.mapbox.com/search/geocode/v6/forward')+'?'+new URLSearchParams({q:raw,access_token:getMapKey(),limit:'5',country:'gb',permanent:'true'});const d=await fetchJSON(url);if(seq!==currentSearch)return;if(!d.features?.length)throw Error('No matching address. Try a postcode or coordinates.');$('searchResults').replaceChildren();d.features.forEach(f=>{const b=document.createElement('button');const label=f.properties?.full_address||f.properties?.name||raw;b.textContent=label;b.onclick=()=>{const coords=f.geometry.coordinates;gotoLocation(coords[1],coords[0],label);$('searchResults').hidden=true};$('searchResults').append(b)});$('searchResults').hidden=false}catch(e){toast(e.message||'Location lookup failed. Please try a postcode or coordinates.')}finally{btn.disabled=false}}
function gotoLocation(lat,lng,label,words,accuracy){if(!Number.isFinite(lat)||!Number.isFinite(lng)||Math.abs(lat)>85||Math.abs(lng)>180){toast('This location is outside the supported map range.');return}if(plan.background.type==='image'){toast('Start a new live-map project to use location search.');return}plan.location={lat,lng,label:String(label).slice(0,250),words:words||null,accuracy:accuracy||null};if(!locked)map.setView([lat,lng],18);if(!plan.prepared)plan.origin={lat,lng};renderLocation();queueSave();toast('Location found. Check the pin against your site entrance.');}
function renderLocation(){if(locationMarker){map.removeLayer(locationMarker);locationMarker=null}if(accuracyCircle){map.removeLayer(accuracyCircle);accuracyCircle=null}const loc=plan.location;$('locationChip').hidden=!loc||plan.background.type==='image';if(!loc)return;$('locationText').textContent=loc.label+(loc.accuracy?' · GPS ±'+Math.round(loc.accuracy)+' m':'');if(plan.background.type==='image')return;locationMarker=L.circleMarker([loc.lat,loc.lng],{radius:7,fillColor:'#007b45',color:'#fff',weight:3,fillOpacity:1,interactive:false}).addTo(map);if(loc.accuracy)accuracyCircle=L.circle([loc.lat,loc.lng],{radius:loc.accuracy,color:'#008151',weight:1,fillOpacity:.1,interactive:false}).addTo(map)}
function currentLocation(){if(locked){toast('Unlock the map before using your current location.');return}if(!navigator.geolocation){toast('Location isn’t supported by this browser. Search by postcode instead.');return}if(!window.isSecureContext){toast('Location needs the hosted HTTPS app. Open your GitHub Pages link.');return}if(plan.background.type==='image'){toast('Start a new live-map project to use your current location.');return}const btn=document.querySelector('[data-action="location"]');btn.disabled=true;toast('Finding your location… Allow location access when asked.');navigator.geolocation.getCurrentPosition(p=>{btn.disabled=false;gotoLocation(p.coords.latitude,p.coords.longitude,'Current location',null,p.coords.accuracy)},e=>{btn.disabled=false;toast(e.code===1?'Location access was declined. Enable it in your browser settings, or search a postcode.':e.code===3?'Location timed out. Try again outside, or search a postcode.':'Your location is unavailable. Search by postcode or coordinates.')},{enableHighAccuracy:true,timeout:18000,maximumAge:30000})}
function w3wDialog(words=''){const loc=plan.location||map.getCenter();const coords=loc.lat.toFixed(6)+', '+loc.lng.toFixed(6);modal('what3words',`<p>Find a three-word address or identify the selected location.</p><label for="w3wInput">Three-word address</label><input id="w3wInput" placeholder="///filled.count.soap" value="${esc(words||plan.location?.words||'')}" autocomplete="off"><div class="button-row full"><button class="btn primary" data-action="resolveWords">Find on this map</button><button class="btn secondary" data-action="openWords">Open what3words ↗</button></div><div class="divider"></div><p>Selected point: <strong>${coords}</strong></p><button class="btn secondary full" data-action="convertWords">Get three words for this point</button>${!getW3WKey()?'<div class="connection-note">In-app conversion needs your what3words API key and an enabled conversion plan. You can open a three-word address on what3words without connecting a key.</div><button class="btn secondary full" data-action="settings">Connect what3words</button>':''}<p class="fineprint">A three-word address identifies a square, not the accuracy of your GPS fix. Confirm the intended entrance on the map.</p>`)}
async function convertWords(){if(!getW3WKey()){toast('Add a what3words API key in Settings to enable conversion.');return}const loc=plan.location||map.getCenter();const coords={lat:loc.lat,lng:loc.lng};try{toast('Looking up the three-word address…');const d=await fetchJSON('https://api.what3words.com/v3/convert-to-3wa?'+new URLSearchParams({coordinates:coords.lat+','+coords.lng,language:'en',key:getW3WKey()}));gotoLocation(d.coordinates.lat,d.coordinates.lng,'///'+d.words,d.words);w3wDialog(d.words)}catch(e){toast(e.message)}}
function startCalibration(){if(plan.background.type!=='image'){modal('Check map scale','<p>The map calculates metres from its geographic coordinates. Use <strong>Measure</strong> to compare a feature against a known site dimension.</p><p>For uploaded drawings, the same tool calibrates the image from two points and a known distance.</p><button class="btn primary full" data-action="measureCheck">Measure a distance</button>');return}modal('Calibrate your map image','<p>Choose a clearly visible feature with a known distance, such as a scale bar. Mark its two ends, then enter the real distance in metres.</p><button class="btn primary full" data-action="markCalibration">Mark two points</button>')}
function markCalibration(){closeModal();closePanel();calibrating=true;calPoints=[];draft=[];mode='select';cv.style.pointerEvents='auto';cv.style.cursor='crosshair';$('toolHint').textContent='Calibration: tap both ends of a known distance.';toast('Tap the first end, then the second end of the known distance.');draw()}
function finishCalibration(){if(C.distance(...calPoints)<.001){calPoints=[];toast('The points are too close. Mark the distance again.');return}modal('Set the real distance',`<p>Enter the distance between your two marks.</p><label for="knownMetres">Known distance (metres)</label><input id="knownMetres" type="number" min="0.01" max="100000" step="0.01" placeholder="e.g. 20"><button class="btn primary full" data-action="applyCalibration">Apply scale</button>${plan.items.length?'<p class="fineprint">Object positions and annotations follow the new scale. Manufactured panels keep their actual dimensions.</p>':''}`);setTimeout(()=>$('knownMetres')?.focus(),50)}
function applyCalibration(){const metres=+$('knownMetres').value;if(!Number.isFinite(metres)||metres<=0||metres>100000){toast('Enter a valid distance greater than zero.');return}checkpoint();const factor=metres/C.distance(...calPoints);plan.background.mpp*=factor;plan.background.calibrated=true;plan.background.calibration={points:calPoints.map(p=>({x:p.x*factor,y:p.y*factor})),metres};plan.items.forEach(q=>{if(q.points)q.points=q.points.map(p=>({x:p.x*factor,y:p.y*factor}));else{q.x*=factor;q.y*=factor;if(q.kind==='rect'||q.kind==='ellipse'){q.l*=factor;q.w*=factor}}});calibrating=false;calPoints=[];plan.prepared=true;closeModal();setMode('select');changed();toast('Image scale calibrated to '+metres+' metres.')}
async function imageFrom(data){return new Promise((res,rej)=>{const im=new Image;im.onload=()=>res(im);im.onerror=()=>rej(Error('The map image could not be read.'));im.src=data})}
async function loadImageFile(file){if(!file)return;try{if(file.size>25*1024*1024)throw Error('Choose a map image smaller than 25 MB.');if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Use a PNG, JPEG or WebP image.');const data=await new Promise((res,rej)=>{const r=new FileReader;r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)});let im=await imageFrom(data);const out=document.createElement('canvas'),ratio=Math.min(1,4096/Math.max(im.width,im.height));out.width=Math.round(im.width*ratio);out.height=Math.round(im.height*ratio);out.getContext('2d').drawImage(im,0,0,out.width,out.height);const clean=out.toDataURL('image/png');if(plan.items.length)await saveLocal(true);checkpoint();plan=emptyProject();plan.name=file.name.replace(/\.[^.]+$/,'')+' plan';plan.origin=null;plan.background={type:'image',data:clean,width:out.width,height:out.height,mpp:1,calibrated:false};plan.prepared=true;selected.clear();view={z:1,x:0,y:0};await restoreBackground();renderUI();queueSave();startCalibration()}catch(e){toast(e.message||'The image could not be opened.')}finally{$('imageFile').value=''}}
async function restoreBackground(){resetReferences();lastRouteAngle=null;frameMode=false;editingPath=null;activeVertex=-1;image=null;if(plan.background.type==='image'){if(activeLayer){map.removeLayer(activeLayer);activeLayer=null}image=await imageFrom(plan.background.data);plan.background.width=image.width;plan.background.height=image.height;$('map').style.visibility='hidden';$('workspace').classList.add('grid-bg');view=plan.imageView||{z:1,x:0,y:0};imageMetrics();$$('[data-layer]').forEach(b=>b.classList.remove('active'))}else{$('map').style.visibility='visible';if(plan.mapView&&Number.isFinite(plan.mapView.zoom)&&Number.isFinite(plan.mapView.center?.lat)&&Number.isFinite(plan.mapView.center?.lng))map.setView([plan.mapView.center.lat,plan.mapView.center.lng],Math.max(3,Math.min(22,plan.mapView.zoom)));else map.setView([plan.origin.lat,plan.origin.lng],18);setLayer(plan.background.layer||'satellite')}setMode(plan.prepared?'select':'pan');renderLocation();draw()}
async function openProjectFile(file){if(!file)return;try{if(file.size>40*1024*1024)throw Error('Project file is too large (maximum 40 MB).');let p=JSON.parse(await file.text());if(p.format!=='trakway-studio')p=C.legacy(p);C.validate(p);if(p.background.type==='image'){const im=await imageFrom(p.background.data);p.background.width=im.width;p.background.height=im.height}if(plan.items.length)await saveLocal(true);checkpoint();plan=p;plan.prepared=true;selected.clear();await restoreBackground();renderUI();queueSave();toast('Editable project opened.')}catch(e){toast(e.message||'The project could not be opened.')}finally{$('projectFile').value=''}}
function safeName(s){return String(s||'Trakway plan').replace(/[\\/:*?"<>|\x00-\x1f]/g,'_').slice(0,100)}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function downloadProject(){downloadBlob(new Blob([JSON.stringify(serial())],{type:'application/json'}),safeName(plan.name)+'.trakway');toast('Project downloaded. Keep this file to reopen or transfer your plan.')}
async function saveLocal(silent=false){try{plan.updatedAt=new Date().toISOString();await dbPut('project:'+plan.id,{...serial(),savedProject:true});if(!silent)toast('Saved in My projects on this device.')}catch(e){if(!silent)toast('Device storage is full or unavailable. Download the project instead.');else throw e}}
async function showProjects(){try{const all=(await dbAll()).sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt)));modal('My projects',`<p>Saved on this device. Use an editable project file to move a plan between devices.</p>${all.length?all.map(p=>`<div class="project-row"><button data-open-project="${esc(p.id)}"><strong>${esc(p.name)}</strong><small>${p.items.length} objects · ${new Date(p.updatedAt).toLocaleDateString('en-GB')}</small></button><button class="icon-btn" data-delete-project="${esc(p.id)}" aria-label="Delete ${esc(p.name)}" data-icon="trash"></button></div>`).join(''):'<div class="empty-state">No saved projects yet.<br>Save your current plan to see it here.</div>'}<button class="btn primary full" data-action="saveLocal">Save current project</button><button class="btn secondary full" data-action="open">Open project file</button>`)}catch(e){toast('Saved projects are unavailable in this browser. Use Download editable project.')}}
async function loadSaved(id){try{const p=await dbGet('project:'+id);if(!p)throw Error('Project not found.');C.validate(p);if(plan.items.length)await saveLocal(true);checkpoint();plan=p;selected.clear();await restoreBackground();renderUI();queueSave();closeModal();toast('Project opened.')}catch(e){toast(e.message)}}
async function newProject(){if(plan.items.length||plan.background.type==='image'){modal('Start a new plan?','<p>Your current plan will be saved in My projects on this device before the new workspace opens.</p><button class="btn primary full" data-action="confirmNew">Save and start new plan</button>');return}await confirmNew()}
async function confirmNew(){try{if(plan.items.length||plan.background.type==='image')await saveLocal(true);clearTimeout(saveTimer);plan=emptyProject();past=[];future=[];selected.clear();view={z:1,x:0,y:0};await restoreBackground();renderUI();queueSave();closeModal()}catch(e){toast('Could not save the current plan. Download it before starting a new one.')}}
function settingsDialog(){modal('Connections & preferences',`<p>Location keys are used by this browser and are excluded from project downloads.</p><h3>Map imagery</h3><label for="mapSource">Satellite source</label><select id="mapSource"><option value="esri" ${settings.mapSource!=='mapbox'?'selected':''}>Esri World Imagery</option><option value="mapbox" ${settings.mapSource==='mapbox'?'selected':''}>Mapbox Satellite</option></select><label for="mapKey">Mapbox public access token</label><input id="mapKey" type="password" autocomplete="off" placeholder="pk.…" value="${esc(getMapKey())}"><p class="fineprint">Optional. Enables full address search and Mapbox imagery. Use a public token restricted to this website. Address results saved in projects use Mapbox permanent geocoding, which requires a suitable account. <a href="https://account.mapbox.com/access-tokens/" target="_blank" rel="noopener">Mapbox account ↗</a></p><h3>what3words</h3><label for="wordsKey">what3words API key</label><input id="wordsKey" type="password" autocomplete="off" value="${esc(getW3WKey())}" placeholder="Your what3words key"><p class="fineprint">Your plan must enable coordinate conversion. <a href="https://accounts.what3words.com/" target="_blank" rel="noopener">what3words account ↗</a></p><label class="toggle-row"><div><strong>Remember keys on this device</strong><span>Leave off on shared devices</span></div><input id="rememberKeys" type="checkbox" role="switch" ${settings.rememberKeys?'checked':''}></label><div class="divider"></div><h3>Panel dimensions</h3><p class="fineprint">Defaults come from your supplied v1.0.1 file. Confirm sizes against the panels in use. Changes apply to new panels.</p><div class="product-edit"><span>Product</span><span>Length · m</span><span>Width · m</span></div>${Object.entries(catalog).map(([k,p])=>`<div class="product-edit"><strong>${p.name}</strong><input aria-label="${p.name} length" id="dim-l-${k}" type="number" min="0.05" max="20" step="0.01" value="${p.l}"><input aria-label="${p.name} width" id="dim-w-${k}" type="number" min="0.05" max="20" step="0.01" value="${p.w}"></div>`).join('')}<button class="btn primary full" data-action="saveSettings">Save settings</button><div class="divider"></div><button class="btn secondary full" data-action="install">Install on this device</button><p class="fineprint">Live maps require internet. Uploaded image projects can be edited offline after the app has been installed and loaded. Satellite imagery is not a live aerial feed.</p>`)}
function saveSettings(){for(const[k,p]of Object.entries(catalog)){const l=+$('dim-l-'+k).value,w=+$('dim-w-'+k).value;if(!Number.isFinite(l)||!Number.isFinite(w)||l<.05||l>20||w<.05||w>20){toast('Panel dimensions must be between 0.05 m and 20 m.');return}}const mapKey=$('mapKey').value.trim(),wordsKey=$('wordsKey').value.trim();if(mapKey&&!mapKey.startsWith('pk.')){toast('Use a Mapbox public token beginning pk.');return}if($('mapSource').value==='mapbox'&&!mapKey){toast('Add a Mapbox public token or select Esri imagery.');return}for(const[k,p]of Object.entries(catalog)){p.l=+$('dim-l-'+k).value;p.w=+$('dim-w-'+k).value}settings={mapSource:$('mapSource').value,mapboxPublicToken:mapKey,what3wordsKey:wordsKey,rememberKeys:$('rememberKeys').checked,catalog};try{const stored={...settings};if(!stored.rememberKeys){delete stored.mapboxPublicToken;delete stored.what3wordsKey}localStorage.setItem('trakway-settings',JSON.stringify(stored))}catch{toast('Settings apply for this session; persistent storage is unavailable.')}renderProducts();if(plan.background.type!=='image')setLayer(plan.background.layer||'satellite');closeModal();toast('Settings updated.')}
function exportDialog(){modal('Export your plan',`<p>${esc(plan.name)} · ${plan.items.length} objects</p><button class="btn primary full" data-action="download" data-icon="download">Editable project · .trakway</button><button class="btn secondary full" data-action="png" data-icon="image">Map & drawing · PNG</button><button class="btn secondary full" data-action="print" data-icon="export">Print / save as PDF</button><button class="btn secondary full" data-action="csv" data-icon="layers">Materials schedule · CSV</button><p class="fineprint">PNG and PDF use the saved paper perimeter, or the visible map when no perimeter is set. The title band is shown inside the paper frame. Live-map projects save the location and drawing; map imagery reloads online.</p><button class="text-button" data-action="fitExport">Fit plan on screen</button>`)}
function csv(){const rows=C.schedule(plan.items);const cell=s=>'"'+String(s).replace(/"/g,'""').replace(/^[=+@-]/,"'")+'"';const data=[['Project','Site','Reference','Product','Type','Length (m)','Width (m)','Quantity','Panel area (m2)'],...rows.map(r=>[plan.name,plan.site,plan.ref,r.name,r.kind,r.l,r.w,r.count,r.kind==='panel'?(r.area).toFixed(2):''])].map(r=>r.map(cell).join(',')).join('\r\n');downloadBlob(new Blob(['\ufeff'+data],{type:'text/csv;charset=utf-8'}),safeName(plan.name)+'-materials.csv');toast('Materials schedule downloaded.')}
async function snapshot(){
 if(draft.length||frameMode)throw Error('Finish the drawing and set the paper perimeter before exporting.');
 const frame=currentPaperRect(),r=frame||{x:0,y:0,w:cv.clientWidth,h:cv.clientHeight};
 if(r.w<25||r.h<25||r.x<-.5||r.y<-.5||r.x+r.w>cv.clientWidth+.5||r.y+r.h>cv.clientHeight+.5)throw Error('Your saved paper frame is outside the visible map. Use Paper frame to compose and set it again before exporting.');
 const scale=2000/r.w,footer=frame?0:135,out=document.createElement('canvas');out.width=2000;out.height=Math.round((r.h+footer)*scale);const c=out.getContext('2d');
 c.fillStyle='#f1f3f2';c.fillRect(0,0,out.width,out.height);c.save();c.scale(scale,scale);c.beginPath();c.rect(0,0,r.w,r.h);c.clip();c.translate(-r.x,-r.y);
 if(plan.background.type==='map'&&activeLayer&&!(planOn&&locked)){
  const tiles=Object.values(activeLayer._tiles||{}),container=$('map').getBoundingClientRect();let bad=false,count=0;
  for(const t of tiles){const el=t.el,b=el.getBoundingClientRect(),x=b.left-container.left,y=b.top-container.top;if(x+b.width<r.x||x>r.x+r.w||y+b.height<r.y||y>r.y+r.h)continue;if(!el.complete||!el.naturalWidth){bad=true;continue}c.drawImage(el,x,y,b.width,b.height);count++}
  if(bad||!count)throw Error('Wait for the map to finish loading before exporting, or choose a different map source.');
 }
 if(image&&plan.background.type==='image'){const p=screen({x:0,y:0}),s=imageFit*view.z;c.drawImage(image,p.x,p.y,image.width*s,image.height*s)}
 paintReferences(c,'plan');plan.items.forEach(q=>paint(q,c,false));paintReferences(c,'power');paintJoints(c);
 if(plan.location&&plan.background.type!=='image'){const p=screen(C.toLocal(plan.location,plan.origin));c.beginPath();c.arc(p.x,p.y,7,0,7);c.fillStyle='#007b45';c.fill();c.strokeStyle='#fff';c.lineWidth=2;c.stroke()}
 c.restore();
 // A visible title band inside the page frame keeps the final image at its paper ratio.
 const band=frame?out.height*.15:footer*scale,top=out.height-band,pad=30;
 c.fillStyle='#ffffffed';c.fillRect(0,top,out.width,band);c.fillStyle='#006b3f';c.fillRect(0,top,out.width,5);
 c.font='700 30px Arial';c.fillText(plan.name,pad,top+44,out.width-360);c.fillStyle='#344a40';c.font='18px Arial';
 c.fillText('SUNBELT RENTALS · TRAKWAY'+(plan.ref?' · '+plan.ref:'')+' · '+new Date().toLocaleDateString('en-GB'),pad,top+74,out.width-360);
 const credit=planOn&&locked?'Plan geometry © OpenStreetMap contributors':plan.background.type==='image'?'User-supplied scaled map image':plan.background.layer==='street'?'© OpenStreetMap contributors':plan.background.layer==='blank'?'Scaled planning grid':settings.mapSource==='mapbox'?'© Mapbox © OpenStreetMap':'Imagery © Esri, Vantor, Earthstar Geographics, GIS User Community';
 c.font='15px Arial';c.fillText(credit+(powerOn&&locked?' · Power assets © OpenStreetMap contributors':'')+' · Design & Production by JW EDS',pad,top+103,out.width-60);
 c.fillText(powerOn&&locked?'OHL data is incomplete. Confirm assets and working arrangements with the network operator.':'Indicative layout. Verify site dimensions, connections and bend arrangements.',pad,top+129,out.width-60);
 if(planOn&&locked||powerOn&&locked){c.font='13px Arial';c.fillText('Reference data retrieved '+new Date((powerData||planData).fetched).toLocaleString('en-GB')+' · Mapped detail only; not a survey.',pad,top+151,out.width-60)}
 const m=+((220/(pixelsPerMetre()*scale)).toPrecision(1)),length=m*pixelsPerMetre()*scale,x=out.width-290,y=top+58;c.strokeStyle='#174d34';c.lineWidth=3;c.beginPath();c.moveTo(x,y-7);c.lineTo(x,y+7);c.moveTo(x,y);c.lineTo(x+length,y);c.moveTo(x+length,y-7);c.lineTo(x+length,y+7);c.stroke();c.fillStyle='#174d34';c.font='700 18px Arial';c.fillText(m+' m',x,y-15);
 try{out.toDataURL('image/png')}catch{throw Error('This map source blocks image export. Use your own map image or the mapped Plan view.')}
 return out;
}

async function exportPNG(){try{toast('Preparing your plan image…');const im=await snapshot();im.toBlob(b=>{if(b){downloadBlob(b,safeName(plan.name)+'.png');toast('Plan image downloaded.')}else toast('The image could not be created.')},'image/png')}catch(e){toast(e.message)}}
async function printPlan(){try{let pageStyle=$('paperPrintStyle');if(!pageStyle){pageStyle=document.createElement('style');pageStyle.id='paperPrintStyle';document.head.append(pageStyle)}pageStyle.textContent='@media print{@page{size:A4 '+(plan.paper?.orientation||'landscape')+';margin:10mm}}';const out=await snapshot(),rows=C.schedule(plan.items);let root=$('printRoot');if(!root){root=document.createElement('div');root.id='printRoot';root.style.display='none';document.body.append(root)}root.innerHTML=`<div class="print-head"><div><h1>${esc(plan.name)}</h1><p>${esc(plan.site)} ${plan.ref?' · '+esc(plan.ref):''}</p></div><img class="print-logo" src="./sunbelt-logo.png" alt="Sunbelt Rentals"></div><img class="print-image" src="${out.toDataURL('image/png')}" alt="Route plan"><table><thead><tr><th>Material</th><th>Dimensions</th><th>Quantity</th><th>Panel area</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${r.l} × ${r.w} m</td><td>${r.count}</td><td>${r.kind==='panel'?r.area.toFixed(2)+' m²':'—'}</td></tr>`).join('')}</tbody></table>${plan.location?`<p>Location: ${esc(plan.location.label)} · ${plan.location.lat.toFixed(6)}, ${plan.location.lng.toFixed(6)}</p>`:''}${plan.notes?'<p>'+esc(plan.notes).replace(/\n/g,'<br>')+'</p>':''}<p class="print-foot">Design & Production by Joseph Whelan EDS · Trakway Route Studio 3.0 · ${new Date().toLocaleDateString('en-GB')}<br>Indicative layout. Check ground conditions, site measurements, connections, overlaps and product dimensions before installation.</p>`;await Promise.all([...root.querySelectorAll('img')].map(im=>im.decode().catch(()=>{})));closeModal();window.print()}catch(e){toast(e.message)}}
function help(){modal('Your route, step by step',`<ol><li><strong>Find the site.</strong> Search a UK postcode, latitude/longitude or connected what3words address. The target button uses your current location.</li><li><strong>Use this area.</strong> The map scale is automatic. For a map image, mark a known distance to calibrate it.</li><li><strong>Choose your panels.</strong> Set a product and single or double width. Draw route points or a pad boundary, then press Finish.</li><li><strong>Refine the layout.</strong> Select, move, rotate, duplicate or group panels. Accessories snap to matching edges. Add labels and dimensions.</li><li><strong>Save and export.</strong> Keep an editable project and export the materials list or a plan image.</li></ol><h3>Touch controls</h3><p>Tap to draw, drag selected objects to move them, and tap a route point to highlight and drag it. The map stays locked while drawing. Unlock to pan or zoom; Paper frame enables pan/pinch composition and a two-finger 90° paper turn. The layers button opens the tools panel. Use Multi-select in the selection bar to select several separate objects.</p><h3>Keyboard & mouse</h3><p>Ctrl / Cmd + Z: undo · Shift + Ctrl / Cmd + Z: redo · Ctrl / Cmd + C / V: copy / paste · Delete: remove · Escape: cancel · Enter: finish · Ctrl / Shift click: multi-select. Scroll to zoom; middle-drag or choose Move map to pan.</p><h3>Map and panel accuracy</h3><p>Maps are north-up. Scale is calculated near your site using geographic coordinates. Use separate projects for widely separated sites. Routes use full panels and can extend past their final point. Freehand routes are simplified into straight runs. Overlapping positions are omitted and orange markers identify bends needing review. Add a matching diversion assembly where needed; no connection or load suitability is certified. Pads include full panels within the boundary, so irregular edges may have gaps.</p><h3>Freehand, areas &amp; symbols</h3><p>Choose Route · freehand or Area · freehand, draw one stroke, lift, then Finish. Single / double wide controls route width. Area panels form one aligned grid inside the exact outline; select longest boundary edge, last route direction or your entered angle in Options. Sabre lateral offsets are optional and limited to 300 mm. Construction symbols have editable schematic dimensions; they are not clearance envelopes.</p><h3>Plan view &amp; overhead lines</h3><p>These drawing-only buttons request local OpenStreetMap data when pressed. Plan view draws mapped footprints, road centrelines and tree points within up to 800 metres. Power assets are queried within one mile of the locked map centre. Data is incomplete; no markers does not mean clear. Unlocking hides both layers. Requests are bounded and never track map scrolling. Tap power symbols in Select mode for recorded details.</p><h3>Offline and device storage</h3><p>The installed app and uploaded-image projects can work offline. Live map tiles and online location searches need internet. Download projects for backup; browser storage may be cleared by the device.</p><button class="btn primary full" data-action="install">Install this app</button>`)}
let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
async function install(){if(installPrompt){await installPrompt.prompt();installPrompt=null;return}modal('Install Trakway Route Studio','<h3>iPhone / iPad</h3><p>Open the hosted app in Safari. Tap <strong>Share → Add to Home Screen</strong>, then Add.</p><h3>Android</h3><p>Open in Chrome. Use the browser menu and choose <strong>Install app</strong> or <strong>Add to Home screen</strong>.</p><h3>Desktop</h3><p>Open in Chrome or Edge and use the install icon in the address bar, when available.</p><p class="connection-note">Use the hosted HTTPS address. Allow the first online load to complete so the app files are available offline.</p>')}
function credits(){modal('JWEDS Designs','<div class="credit-lockup"><img src="./jweds-white.png" alt="Joseph Whelan EDS" style="max-width:100%;width:260px;height:auto"><span>DESIGNS</span><p>Design &amp; Production by<br>Joseph Whelan EDS</p></div><p class="full">Trakway Route Studio · Version 3.0<br>Created for Sunbelt Rentals Trakway planning.</p>')}
let multiSelect=false;
function editSelected(){const qs=plan.items.filter(q=>selected.has(q.id));if(qs.length!==1){toast('Select one object to edit its details.');return}const q=qs[0];modal('Edit '+(q.name||q.kind),`${q.kind==='text'?'<label for="editText">Label</label><input id="editText" maxlength="120" value="'+esc(q.text)+'">':''}${!q.points?'<label for="editAngle">Rotation (degrees)</label><input id="editAngle" type="number" step="1" value="'+Math.round((q.a||0)/C.DEG)+'">':''}${['rect','ellipse','symbol'].includes(q.kind)?'<div class="field-grid"><div><label for="editLength">Width (m)</label><input id="editLength" type="number" min="0.05" step="0.1" value="'+q.l+'"></div><div><label for="editWidth">Height (m)</label><input id="editWidth" type="number" min="0.05" step="0.1" value="'+q.w+'"></div></div>':''}<label for="editColour">Colour</label><input id="editColour" type="color" value="${q.colour||'#ffffff'}"><button class="btn primary full" data-action="applyEdit" data-item="${q.id}">Apply changes</button>`)}
function applyEdit(el){const q=plan.items.find(q=>q.id===el.dataset.item);if(!q)return;const angle=$('editAngle')?+$('editAngle').value:0,l=$('editLength')?+$('editLength').value:1,w=$('editWidth')?+$('editWidth').value:1;if(!Number.isFinite(angle)||!Number.isFinite(l)||!Number.isFinite(w)||l<.05||w<.05||l>100000||w>100000){toast('Enter valid dimensions and rotation.');return}if($('editText')&&!$('editText').value.trim()){toast('The label cannot be empty.');return}checkpoint();if($('editAngle'))q.a=angle*C.DEG;if($('editText'))q.text=$('editText').value.trim();if($('editLength')){q.l=l;q.w=w}q.colour=$('editColour').value;closeModal();changed()}
const actions={toggleDraw,drawOptions,annotationOptions,removePoint,editRoute,togglePlanView:()=>toggleReference('plan'),togglePower:()=>toggleReference('power'),paper:startPaper,rotatePaper,savePaper,clearPaper,help,settings:settingsDialog,saveSettings,export:exportDialog,projects:showProjects,closeModal,closePanel,openPanel:()=>{$('sidebar').classList.add('open');$('panelScrim').hidden=false},useArea,location:currentLocation,zoomIn:()=>zoom(1),zoomOut:()=>zoom(-1),fit:fitPlan,north:()=>toast(plan.background.type==='image'?'Image orientation is as uploaded.':'The live map is always north-up.'),credits,undo:()=>historyStep(false),redo:()=>historyStep(true),finish,cancelDraft:cancelDrawing,duplicate,delete:deleteSelected,rotateLeft:()=>rotateSelected(-5),rotateRight:()=>rotateSelected(5),group:groupSelection,download:downloadProject,saveLocal:()=>saveLocal(),open:()=>{closeModal();$('projectFile').click()},upload:()=>{closeModal();if(plan.items.length){modal('Use a map image','<p>Your current plan will be saved in My projects. The uploaded image starts a new plan with its own scale.</p><button class="btn primary full" data-action="pickImage">Choose image</button>')}else $('imageFile').click()},pickImage:()=>{closeModal();$('imageFile').click()},new:newProject,confirmNew,calibrate:startCalibration,markCalibration,applyCalibration,measureCheck:()=>{closeModal();setMode('measure')},w3w:()=>w3wDialog(),resolveWords:()=>{const w=normalWords($('w3wInput').value);if(!/^[\p{L}]+\.[\p{L}]+\.[\p{L}]+$/u.test(w)){toast('Enter three words separated by dots.');return}if(!getW3WKey()){toast('Connect a what3words API key in Settings for in-app lookup.');return}$('search').value='///'+w;closeModal();searchSite()},openWords:()=>{const w=normalWords($('w3wInput').value);if(!/^[\p{L}]+\.[\p{L}]+\.[\p{L}]+$/u.test(w)){toast('Enter a three-word address first.');return}window.open('https://what3words.com/'+encodeURIComponent(w),'_blank','noopener,noreferrer')},convertWords,csv,png:exportPNG,print:printPlan,fitExport:()=>{closeModal();fitPlan()},install,edit:editSelected,applyEdit,multi:el=>{multiSelect=!multiSelect;el.classList.toggle('multi-active',multiSelect);el.setAttribute('aria-pressed',String(multiSelect));toast(multiSelect?'Multi-select on: tap objects to add or remove them.':'Multi-select off.')}};
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-action]');if(!b)return;try{if(b.dataset.action){await actions[b.dataset.action]?.(b);return}if(b.dataset.mode)setMode(b.dataset.mode);if(b.dataset.tab)switchTab(b.dataset.tab);if(b.dataset.layer)setLayer(b.dataset.layer);if(b.dataset.product){$('product').value=b.dataset.product;renderProducts();syncDrawingUI()}if(b.dataset.openProject)await loadSaved(b.dataset.openProject);if(b.dataset.deleteProject){const id=b.dataset.deleteProject;modal('Delete saved project?','<p>This removes the saved copy from this device. Downloaded project files are unaffected.</p><button class="btn primary full" id="confirmDeleteProject">Delete saved copy</button>');$('confirmDeleteProject').onclick=async()=>{await dbDelete('project:'+id);showProjects()}}}catch(e){toast(e.message||'That action could not be completed.')}});
$('panelScrim').onclick=closePanel;$('searchForm').onsubmit=searchSite;$('imageFile').onchange=e=>loadImageFile(e.target.files[0]);$('projectFile').onchange=e=>openProjectFile(e.target.files[0]);$('product').onchange=()=>{renderProducts();syncDrawingUI()};
$('drawMode').onchange=e=>setMode(e.target.value);$('drawProduct').onchange=e=>{$('product').value=e.target.value;renderProducts();syncDrawingUI()};$('drawWidth').onchange=e=>{$('routeWidth').value=e.target.value};$('routeWidth').onchange=()=>syncDrawingUI();$('drawAngle').oninput=e=>{$('angle').value=e.target.value};$('angle').oninput=()=>{$('drawAngle').value=$('angle').value};
for(const[id,prop]of [['projectName','name'],['siteName','site'],['projectRef','ref'],['projectNotes','notes']])$(id).addEventListener('input',()=>{plan[prop]=$(id).value;queueSave()});
['annColour','annSize','shapeKind','lineStyle','opacity'].forEach(id=>$(id).addEventListener('input',draw));
document.addEventListener('keydown',e=>{if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||$('modal').open)return;const mod=e.ctrlKey||e.metaKey;if(mod&&e.key.toLowerCase()==='z'){e.preventDefault();historyStep(e.shiftKey)}else if(mod&&e.key.toLowerCase()==='y'){e.preventDefault();historyStep(true)}else if(mod&&e.key.toLowerCase()==='c'){e.preventDefault();copy()}else if(mod&&e.key.toLowerCase()==='v'){e.preventDefault();paste()}else if(mod&&e.key.toLowerCase()==='s'){e.preventDefault();downloadProject()}else if(mod&&e.key.toLowerCase()==='a'){e.preventDefault();selected=new Set(plan.items.map(q=>q.id));renderSelection();draw()}else if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();deleteSelected()}else if(e.key==='Escape'){cancelDrawing();selected.clear();setMode(locked?'select':'pan');renderSelection();draw()}else if(e.key==='Enter'&&draft.length){e.preventDefault();finish()}else if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();if(locked&&!frameMode)return;const dx=e.key==='ArrowLeft'?-50:e.key==='ArrowRight'?50:0,dy=e.key==='ArrowUp'?-50:e.key==='ArrowDown'?50:0;if(plan.background.type==='image'){view.x-=dx;view.y-=dy;draw()}else map.panBy([dx,dy],{animate:false})}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&ready){clearTimeout(saveTimer);dbPut('draft',serial()).catch(()=>{})}});window.addEventListener('pagehide',()=>{if(ready)dbPut('draft',serial()).catch(()=>{})});window.addEventListener('offline',()=>{notice('Offline · live maps need internet. Your drawing remains editable.');toast('You’re offline. Uploaded image projects remain available.')});window.addEventListener('online',()=>{notice('');activeLayer?.redraw();toast('Back online.')});
async function boot(){renderProducts();try{const saved=await dbGet('draft');if(saved){C.validate(saved);plan=saved;await restoreBackground();toast('Your last plan has been restored.')}else setLayer('satellite')}catch{setLayer('satellite');$('saveStatus').textContent='Download projects to keep your work'}ready=true;resize();renderUI();setMode(plan.prepared?'select':'pan');if(location.protocol==='file:')modal('Open the hosted app','<p>This PWA works best from its HTTPS website. Publish the package to GitHub Pages, then open the hosted link to enable current location, online search and installation.</p>');if('serviceWorker'in navigator&&/^https?:$/.test(location.protocol))navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(()=>{toast('Offline installation is unavailable in this browser. Online planning still works.')})}
new ResizeObserver(resize).observe($('workspace'));boot();
